const normN=s=>String(s||'').toUpperCase().replace(/\s+/g,' ').trim();
function toISO(v){if(v===''||v==null)return'';if(typeof v==='number')return new Date(Math.round((v-25569)*864e5)).toISOString().slice(0,10);
  const m=String(v).match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');
  return /^\d{4}-\d{2}-\d{2}$/.test(String(v))?String(v):''}
function parseSheet(ws){
  const A=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:true});
  const hi=A.findIndex(r=>r.some(c=>/produk|nama barang|nama/i.test(String(c))));
  if(hi<0)throw new Error('Header "Produk" tidak ditemukan');
  const h1=A[hi],h2=A[hi+1]||[];const sub=h2.some(c=>/^(ctn|pcs)$/i.test(String(c).trim()));
  const map={};
  h1.forEach((_,ci)=>{const t=(String(h1[ci])+' '+(sub?String(h2[ci]):'')).toLowerCase();
    let k=null;
    if(/kode|sku|barcode|plu/.test(t))k='kd';else if(/principle|prinsipal/.test(t))k='p';else if(/produk|nama/.test(t))k='n';
    else if(/pos/.test(t))k='pos';else if(/total/.test(t))k='t';else if(/rusak/.test(t))k='r';
    else if(/expired|kadaluarsa/.test(t))k='e';else if(/ket/.test(t))k='k';
    else if(/ctn|karton/.test(t))k='c';else if(/\bpcs\b/.test(t))k='s';
    if(k&&!(k in map))map[k]=ci});
  if(!('n' in map))throw new Error('Kolom Produk tidak ditemukan');
  const out=[];
  for(let i=hi+(sub?2:1);i<A.length;i++){const r=A[i],n=String(r[map.n]??'').trim();if(!n)continue;
    const o={p:String(map.p!=null?r[map.p]:'').trim()||'Lainnya',n,_:{}};
    ['c','s','r','t','pos'].forEach(k=>{if(k in map){const v=r[map[k]];o._[k]=(v===''||v==null)?'':(Number(v)||0)}});
    if('kd' in map){const kv=String(r[map.kd]??'').trim();if(kv)o._.kd=kv}if('e' in map)o._.e=toISO(r[map.e]);if('k' in map)o._.k=String(r[map.k]??'');
    out.push(o)}
  return out;
}
$('is').onclick=async()=>{
  const f=$('iF').files[0];if(!f){toast('Pilih file dulu');return}
  try{
    const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});
    const rows=parseSheet(wb.Sheets[wb.SheetNames[0]]);
    const mode=document.querySelector('input[name=im]:checked').value;
    if(mode==='replace'){
      if(!confirm('Ganti seluruh daftar ('+S.rows.length+' barang) dengan '+rows.length+' barang dari file?'))return;
      S.rows=rows.map(o=>Object.assign({p:o.p,n:o.n,kd:'',c:'',i:'',s:'',r:'',t:'',pos:'',e:'',k:''},o._));
    }else{
      const idx=new Map(S.rows.map((r,i)=>[normN(r.n),i]));let upd=0,add=0;
      rows.forEach(o=>{const i=idx.get(normN(o.n));
        if(i!=null){Object.assign(S.rows[i],o._);if(o._.c!==undefined||o._.s!==undefined)S.rows[i].t=o._.t??'';upd++}
        else{S.rows.push(Object.assign({p:o.p,n:o.n,kd:'',c:'',i:'',s:'',r:'',t:'',pos:'',e:'',k:'BARU'},o._));add++}});
      toast(upd+' diupdate, '+add+' barang baru');
    }
    $('dlgI').close();soSelect(-1);save();fillFilters();render();
    if(mode==='replace')toast('Daftar barang diganti: '+S.rows.length+' item');
  }catch(err){alert('Gagal import: '+err.message)}
};
// ===== Panel SO per barang =====
let cur=-1,dirty=false,saving=false,act=0,soM=[],anc={f:null,p:null},tbase=null;
const intOk=v=>/^\d{1,9}$/.test(String(v).trim());
const posStr=r=>r.pos===''||r.pos==null?'':String(r.pos);
const fisikOf=r=>filled(r)?String(tot(r)):'';
const fmtTs=t=>new Date(t).toLocaleString('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'});
const fmtS=d=>d==null?'–':(d>0?'+':'')+d;
const fmtN=v=>v==null||v===''?'–':Number(v).toLocaleString('id-ID');
function stat(f,p){if(!intOk(f)||!intOk(p))return null;const d=Number(f)-Number(p);return{d,st:d===0?'ok':d>0?'lebih':'kurang'}}
function soLast(){$('soLast').textContent=S.lastSaved?'Terakhir disimpan: '+fmtTs(S.lastSaved):'Belum ada perubahan yang disimpan'}
function soLoad(){if(cur<0)return;const r=S.rows[cur];anc={f:fisikOf(r)===''?null:Number(fisikOf(r)),p:posStr(r)===''?null:Number(r.pos)};$('soF').value=fisikOf(r);$('soP').value=posStr(r);$('soErr').textContent='';soUpdate();soHist()}
function soUpdate(){
  if(cur<0)return;const r=S.rows[cur],f=$('soF').value,p=$('soP').value;
  dirty=f.trim()!==fisikOf(r)||p.trim()!==posStr(r);
  const s=stat(f,p),b=$('soBadge'),sv=$('soS');
  b.className='badge '+(s?s.st:'na');
  b.textContent=!s?'BELUM LENGKAP':s.st==='ok'?'SESUAI':s.st==='lebih'?'SELISIH LEBIH':'SELISIH KURANG';
  sv.textContent=s?fmtS(s.d)+' PCS':'–';sv.className=s?(s.d===0?'zero':s.d<0?'neg':'pos'):'';
  $('soW').textContent=/^-\d+$/.test(f.trim())?'⚠ Hasil perhitungan stok fisik negatif – periksa angka POS.':s&&s.d<0?'⚠ Stok POS lebih besar dari fisik – perlu diperiksa.':'';
  const sf=fisikOf(r),sp=posStr(r);
  $('soInfo').textContent=sf!==''&&sp!==''&&intOk(f)&&intOk(p)?`Perubahan POS: ${fmtS(Number(p)-Number(sp))} · Perubahan fisik: ${fmtS(Number(f)-Number(sf))} · Selisih: ${fmtS(Number(sf)-Number(sp))} → ${fmtS(Number(f)-Number(p))}`:'';
  $('soFo').textContent='Tersimpan: '+(fisikOf(r)===''?'belum diisi':fmtN(fisikOf(r)));
  $('soPo').textContent='Tersimpan: '+(posStr(r)===''?'kosong':fmtN(r.pos));
  $('soDirty').textContent=dirty?'● Ada perubahan yang belum disimpan':'';
  $('soSave').disabled=saving||!dirty;
}
function soHist(){
  if(cur<0)return;const r=S.rows[cur];const L=S.log.filter(e=>e.n===r.n).slice(-3).reverse();
  $('soH').innerHTML=L.length?'<b>Riwayat terakhir:</b><br>'+L.map(e=>`${fmtTs(e.ts)} · Fisik ${fmtN(e.fb)}→${fmtN(e.fa)} · POS ${fmtN(e.pb)}→${fmtN(e.pa)} · Selisih ${fmtS(e.sb)}→${fmtS(e.sa)}${e.dp!=null?' (Δ POS '+fmtS(e.dp)+')':''}${e.u?' · '+esc(e.u):''}`).join('<br>'):'Belum ada riwayat SO untuk barang ini.';
}
function soSelect(i,sc){
  if(i!==cur&&i>=0&&dirty&&!confirm('Perubahan belum disimpan akan dibuang. Lanjut pilih barang lain?'))return;
  cur=i;dirty=false;$('soL').hidden=true;$('soNF').hidden=true;$('soD').hidden=i<0;
  if(i<0){$('soQ').value='';return}
  const r=S.rows[i];$('soQ').value=r.n;$('soName').textContent=r.n;
  $('soMeta').textContent='Kode: '+(r.kd||'–')+'  ·  Principle: '+r.p;
  soLoad();if(sc)$('soPanel').scrollIntoView({behavior:'smooth',block:'center'});
  if(sc)setTimeout(()=>$('soF').focus(),250);
}
function soSearch(){
  const q=$('soQ').value.trim().toLowerCase(),L=$('soL');
  if(!q){L.hidden=true;$('soNF').hidden=true;return}
  const tk=q.split(/\s+/),m=[];
  S.rows.forEach((r,i)=>{const h=(r.n+' '+(r.kd||'')+' '+r.p).toLowerCase();if(tk.every(t=>h.includes(t)))m.push(i)});
  act=0;soM=m.slice(0,8);L.hidden=!m.length;$('soNF').hidden=!!m.length;$('soNQ').textContent=$('soQ').value.trim();
  L.innerHTML=soM.map((i,k)=>{const r=S.rows[i];return`<div class="so-i${k===0?' on':''}" data-i="${i}"><span>${esc(r.n)}</span><small>${esc(r.kd||'')} ${esc(r.p)}</small></div>`}).join('')+(m.length>8?`<div class="so-more">+${m.length-8} lainnya – persempit pencarian</div>`:'');
}
function soAct(d){const it=[...$('soL').querySelectorAll('.so-i')];if(!it.length)return;act=(act+d+it.length)%it.length;it.forEach((x,k)=>x.classList.toggle('on',k===act));it[act].scrollIntoView({block:'nearest'})}
$('soQ').addEventListener('input',soSearch);
$('soQ').addEventListener('focus',()=>{if($('soQ').value.trim()&&cur<0)soSearch()});
$('soQ').addEventListener('keydown',e=>{
  if(e.key==='ArrowDown'){e.preventDefault();soAct(1)}else if(e.key==='ArrowUp'){e.preventDefault();soAct(-1)}
  else if(e.key==='Enter'){e.preventDefault();if(soM.length&&!$('soL').hidden)soSelect(soM[act],true)}
  else if(e.key==='Escape')$('soL').hidden=true;
});
