$('soSave').onclick=()=>{
  if(saving||cur<0)return;
  const fv=$('soF').value.trim(),pv=$('soP').value.trim(),err=$('soErr');
  if(fv===''||pv===''){err.textContent='Stok fisik dan stok POS wajib diisi (isi 0 jika memang kosong).';return}
  if(!intOk(fv)||!intOk(pv)){err.textContent='Isi dengan angka bulat 0 atau lebih – tanpa minus, koma, atau huruf.';return}
  if(!dirty){toast('Tidak ada perubahan');return}
  saving=true;$('soSave').disabled=true;
  const r=S.rows[cur],f=Number(fv),p=Number(pv),fb=fisikOf(r)===''?null:Number(fisikOf(r)),pb=posStr(r)===''?null:Number(r.pos);
  const old={t:r.t,pos:r.pos},oldLast=S.lastSaved,oldLen=S.log.length,now=Date.now();
  r.t=f;r.pos=p;S.lastSaved=now;
  S.log.push({ts:now,kd:r.kd||'',n:r.n,fb,fa:f,pb,pa:p,dp:pb==null?null:p-pb,sb:fb==null||pb==null?null:fb-pb,sa:f-p,u:$('mPet').value.trim()});
  if(S.log.length>3000)S.log.splice(0,S.log.length-3000);
  const ok=save();
  if(!ok){
    r.t=old.t;r.pos=old.pos;S.lastSaved=oldLast;S.log.length=Math.min(S.log.length,oldLen);
    err.textContent='GAGAL menyimpan: penyimpanan browser tidak tersedia atau penuh. Data TIDAK tersimpan.';
  }else{
    const sc=$('tb').parentElement.scrollTop;render();$('tb').parentElement.scrollTop=sc;
    soLoad();soLast();toast('✔ Tersimpan '+fmtTs(now));
  }
  saving=false;soUpdate();
};
function showLog(name){
  const L=(name?S.log.filter(e=>e.n===name):S.log).slice().reverse();
  $('lT').textContent=name?'Riwayat: '+name:'Log semua perubahan SO';
  $('lB').innerHTML=L.map(e=>`<tr><td>${fmtTs(e.ts)}</td><td>${esc(e.kd||'–')}</td><td>${esc(e.n)}</td><td style="text-align:right;font-family:var(--m)">${fmtN(e.fb)} → ${fmtN(e.fa)}</td><td style="text-align:right;font-family:var(--m)">${fmtN(e.pb)} → ${fmtN(e.pa)}</td><td style="text-align:right;font-family:var(--m)">${fmtS(e.dp)}</td><td style="text-align:right;font-family:var(--m)">${fmtS(e.sb)} → ${fmtS(e.sa)}</td><td>${esc(e.u||'')}</td></tr>`).join('')||'<tr><td colspan="8" style="padding:24px;text-align:center;color:#aab0ba">Belum ada riwayat.</td></tr>';
  $('dlgL').showModal();
}
$('soLog').onclick=()=>{if(cur>=0)showLog(S.rows[cur].n)};
$('logAll').onclick=()=>showLog(null);
$('lc').onclick=()=>$('dlgL').close();
const NUMF=['c','i','s','t','pos'];
$('tb').addEventListener('focusin',e=>{
  const t=e.target,tr=t.closest('tr');if(!tr||!NUMF.includes(t.dataset.f))return;
  const ix=Number(tr.dataset.i);if(tbase&&tbase.ix===ix)return;
  const r=S.rows[ix],f=fisikOf(r),p=posStr(r);tbase={ix,f:f===''?null:Number(f),p:p===''?null:Number(p)};
});
function posFollow(r,tr,v){
  const ix=Number(tr.dataset.i);if(!tbase||tbase.ix!==ix||tbase.f==null||tbase.p==null)return;
  let nf=tbase.f;const pv=String(v).trim();
  if(intOk(pv)){const c=tbase.f+(Number(pv)-tbase.p);if(c>=0)nf=c;else toast('Hasil stok fisik negatif – periksa angka POS')}
  r.t=nf;tr.querySelector('.tot').value=nf;
}
$('tb').addEventListener('change',e=>{
  const t=e.target,tr=t.closest('tr');if(!tr||!tbase||!NUMF.includes(t.dataset.f))return;
  const ix=Number(tr.dataset.i);if(tbase.ix!==ix)return;
  const r=S.rows[ix],f=fisikOf(r),p=posStr(r),fa=f===''?null:Number(f),pa=p===''?null:Number(p);
  if(fa===tbase.f&&pa===tbase.p)return;
  const now=Date.now();
  S.log.push({ts:now,kd:r.kd||'',n:r.n,fb:tbase.f,fa,pb:tbase.p,pa,dp:tbase.p==null||pa==null?null:pa-tbase.p,sb:tbase.f==null||tbase.p==null?null:tbase.f-tbase.p,sa:fa==null||pa==null?null:fa-pa,u:$('mPet').value.trim()});
  S.lastSaved=now;if(!save())toast('GAGAL menyimpan – data tidak tersimpan permanen');
  soLast();if(cur===ix&&!dirty)soLoad();tbase={ix,f:fa,p:pa};
});
$('tb').addEventListener('focusout',e=>{setTimeout(()=>{if(!$('tb').contains(document.activeElement))tbase=null},0)});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
soLast();
fillFilters();render();
